                                       &PyArray_Type, &cov_array))
        return NULL;

    if (PyArray_NDIM(weights_array) != 1 || PyArray_NDIM(cov_array) != 2) {
        PyErr_SetString(PyExc_ValueError, "weights must be 1D and cov_matrix must be 2D");
        return NULL;
    }

    n = PyArray_DIM(weights_array, 0);
    if (PyArray_DIM(cov_array, 0) != n || PyArray_DIM(cov_array, 1) != n) {
        PyErr_SetString(PyExc_ValueError, "cov_matrix dimensions do not match weights");
        return NULL;
    }

    if (PyArray_TYPE(weights_array) != NPY_DOUBLE) {
        PyErr_SetString(PyExc_TypeError, "weights must be float64 array");
        return NULL;
    }
    if (PyArray_TYPE(cov_array) != NPY_DOUBLE) {
        PyErr_SetString(PyExc_TypeError, "cov_matrix must be float64 array");
        return NULL;
    }

    if (!PyArray_IS_C_CONTIGUOUS(weights_array) || !PyArray_IS_C_CONTIGUOUS(cov_array)) {
        PyErr_SetString(PyExc_ValueError, "arrays must be C-contiguous");
        return NULL;
    }

    weights_data = (double *)PyArray_DATA(weights_array);
    cov_data = (double *)PyArray_DATA(cov_array);

    temp = (double *)malloc(n * sizeof(double));
    if (temp == NULL) {
        return PyErr_NoMemory();
    }

    // temp[i] = sum_j cov[i][j] * weights[j]
    for (i = 0; i < n; i++) {
        double row_sum = 0.0;
        double *cov_row = cov_data + i * n;
        for (j = 0; j < n; j++) {
            row_sum += cov_row[j] * weights_data[j];
        }
        temp[i] = row_sum;
    }

    risk_squared = 0.0;
    for (i = 0; i < n; i++) {
        risk_squared += weights_data[i] * temp[i];
    }

    free(temp);

    return PyFloat_FromDouble(sqrt(risk_squared));
}
