    if (!PyArg_ParseTuple(args, "O!O!", &PyArray_Type, &weights_array,
                                       &PyArray_Type, &returns_array))
        return NULL;

    if (PyArray_NDIM(weights_array) != 1 || PyArray_NDIM(returns_array) != 1) {
        PyErr_SetString(PyExc_ValueError, "weights and returns must be 1D");
        return NULL;
    }

    n = PyArray_DIM(weights_array, 0);
    if (PyArray_DIM(returns_array, 0) != n) {
        PyErr_SetString(PyExc_ValueError, "dimensions do not match");
        return NULL;
    }

    if (PyArray_TYPE(weights_array) != NPY_DOUBLE || PyArray_TYPE(returns_array) != NPY_DOUBLE) {
        PyErr_SetString(PyExc_TypeError, "arrays must be float64");
        return NULL;
    }

    if (!PyArray_IS_C_CONTIGUOUS(weights_array) || !PyArray_IS_C_CONTIGUOUS(returns_array)) {
        PyErr_SetString(PyExc_ValueError, "arrays must be C-contiguous");
        return NULL;
