    weights_data = (double *)PyArray_DATA(weights_array);
    returns_data = (double *)PyArray_DATA(returns_array);

    for (i = 0; i < n; i++) {
        total_return += weights_data[i] * returns_data[i];
    }

    return PyFloat_FromDouble(total_return);
}
